// === Tab: mySketch.js ===
let pBuf;
let _gl, gl;
let myPointShader;

const NUM = 100;
const POINT_NUM = NUM * NUM;
let positions = new Float32Array(POINT_NUM * 3);  // type を変更しないこと
let vec = new Float32Array(POINT_NUM * 3);
let vel;

let _SIZE;

let bg;

function setup(){
  // _gl = createCanvas(w=600, w, WEBGL);
  _gl = createCanvas(1112, 834, WEBGL);
  _SIZE = max(width, height);
	colorMode(HSB,360,100,100,100);

  gl = _gl.GL;
  myPointShader = createShader(vsPoint, fsPoint);

	initPositionsAndVectors();
	vel = 2;
}

function draw() {
	background(0);
	let col = color(map(vel,0,10,10,360),map(vel,0,10,100,100),map(vel,0,10,100,100));

	shader(myPointShader);
  myPointShader.setUniform("uCount", frameCount);  // custom uniform
  myPointShader.setUniform("uResolution", [width, height]);  // custom uniform
  myPointShader.setUniform("uColor", [red(col)/255.0, green(col)/255.0, blue(col)/255.0]);  // custom uniform

	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) { vel = 10;  updateVector(); }
	else { vel *= 0.95; }  // decelerate

	movePositions();  // move vertex

  setVbo(POINT_NUM);  // pass to vertex shader via vbo, and draw

  gl.drawArrays(gl.Points, 0, pBuf.model.vertices.length);  // draw with shader

	/* You can try to compare FPS with drawing only p5.js! */
	// stroke(255);  strokeWeight(1);
	// for (let i=0; i<POINT_NUM; i++) {
	// 	point(positions[i*3]-width/2, positions[i*3+1]-height/2);
	// }
}

/* Initialize vertex positions and vector */
function initPositionsAndVectors(){
  let x, y;
  for(let i = 0; i < POINT_NUM; i++){
    x = map(i%NUM, 0, NUM-1, width/2-250, width/2+250);
    y = map((i/NUM)%NUM, 0, NUM-1, height/2-250, height/2+250);
    positions[i*3] = x;
    positions[i*3+1] = y;
    positions[i*3+2] = 0;
    vec[i*3] = 0;
    vec[i*3+1] = 0;
    vec[i*3+2] = 0;
  }
}

/* Update vector from vertex position, mouse position and previous vector
(vertex の座標・速度ベクトルとマウス座標を元に速度ベクトルを更新) */
function updateVector(){
  for(let i = 0; i < POINT_NUM; i++){
		let d = sqrt(sq((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - positions[i*3]) + sq((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - positions[i*3+1])) * 5;
		let vx = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - positions[i*3]) / d;
		let vy = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - positions[i*3+1]) / d;
		vx += vec[i*3];
		vy += vec[i*3+1];
		d = sqrt(sq(vx) + sq(vy));
		vec[i*3] = vx / d;
		vec[i*3+1] = vy / d;
  }
}

/* Move vertex from vector and velocity */
function movePositions(){
  for(let i = 0; i < POINT_NUM; i++){
    positions[i*3] += vec[i*3] * vel;
    positions[i*3+1] += vec[i*3+1] * vel;
  }
}

/* Pass vertex positions via vbo to vertex shader, and draw */
function setVbo(num){
  /* Create vbo (vertex buffer object), manually (直接 vbo を作成する) */
  const gId = `myPoints|${num}`;
  if(!this._renderer.geometryInHash(gId)){
    const myPointsGeom = new p5.Geometry();
    let v = createVector();
    for(let i = 0; i < num; i++){
      myPointsGeom.vertices.push(v.copy());
    }
    pBuf = this._renderer.createBuffers(gId, myPointsGeom);
  }

  /* Set attributes as dynamic, manually (直接 vbo を動的に変更できるようにする) */
  _gl._setPointUniforms(myPointShader);
  _gl._bindBuffer(_gl.immediateMode.buffers.point, gl.ARRAY_BUFFER,
                  _gl._vToNArray(pBuf.model.vertices), Float32Array, gl.DYNAMIC_DRAW);
  myPointShader.enableAttrib(myPointShader.attributes.aPosition, 3);

	/* Pass vertex positions via vbo to vertex shader (頂点座標を渡す)  */
  gl.bufferSubData(gl.ARRAY_BUFFER, 0, positions);
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: vert ===
let vsPoint =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"attribute float aIndex;" +
"uniform mat4 uModelViewMatrix;" +
"uniform mat4 uProjectionMatrix;" +
"uniform float uCount;" +
"uniform vec2 uResolution;" +
"void main() {" +
"  vec3 p = aPosition;" +
"  p.xy -= uResolution / 2.;" +
"  vec4 positionVec4 =  vec4(p, 1.0);" +
"  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;" +  // vertex shader 側は何もしない (pointing するだけ)
"  gl_PointSize = 4.;" +
"}";

// === Tab: frag ===
let fsPoint =
"precision mediump float;" +
"precision mediump int;" +
"uniform vec3 uColor;" +
"void main(){" +
"  gl_FragColor = vec4(uColor, 1.);" +  // fragment shader 側は何もしない (color mapping するだけ)
"}";

